import os
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
os.makedirs('/root/output', exist_ok=True)
path='/root/data/workbook.xlsx'
wb=load_workbook(path, data_only=False)
print('Workbook sheets:', wb.sheetnames)
ws=wb['Task']
wd=wb['Data']
print('\nTask series codes in D12:D17, D19:D24, D26:D31:')
for start,end in [(12,17),(19,24),(26,31)]:
    print(f'Rows {start}-{end}:')
    for r in range(start,end+1):
        print(f'  D{r}: {ws.cell(r,4).value!r}')
print('\nTask year headers H10:L10:')
for c in range(8,13):
    v=ws.cell(10,c).value
    print(f'  {get_column_letter(c)}10: {v!r} ({type(v).__name__})')
print('\nTask labels/row content rows 35-40, 42-47, 50 columns A-G:')
for r in list(range(35,41))+list(range(42,48))+[50]:
    nonempty=[]
    for c in range(1,8):
        v=ws.cell(r,c).value
        if v is not None:
            nonempty.append((get_column_letter(c), v))
    print(f'  Row {r}: {nonempty}')
print('\nData rows 21-38 used range inspection:')
nonempty_cols=set()
for r in range(21,39):
    for c in range(1, wd.max_column+1):
        if wd.cell(r,c).value is not None:
            nonempty_cols.add(c)
if nonempty_cols:
    minc,maxc=min(nonempty_cols),max(nonempty_cols)
else:
    minc,maxc=1,wd.max_column
print(f'  Non-empty columns in rows 21-38: {get_column_letter(minc)}:{get_column_letter(maxc)} ({minc}:{maxc})')
for r in range(21,39):
    cells=[]
    for c in range(minc,maxc+1):
        v=wd.cell(r,c).value
        if v is not None:
            cells.append(f'{get_column_letter(c)}{r}={v!r}({type(v).__name__})')
    print(f'  Row {r}: ' + '; '.join(cells))
print('\nCandidate year cells in Data rows 21-38:')
for r in range(21,39):
    years=[]
    for c in range(minc,maxc+1):
        v=wd.cell(r,c).value
        is_year = (isinstance(v, int) and 1900 <= v <= 2100) or (isinstance(v, str) and v.strip().isdigit() and 1900 <= int(v.strip()) <= 2100)
        if is_year:
            years.append(f'{get_column_letter(c)}{r}={v!r}({type(v).__name__})')
    if years:
        print(f'  Row {r}: ' + ', '.join(years))
print('\nCandidate Task series code matches in Data rows 21-38:')
task_rows=list(range(12,18))+list(range(19,25))+list(range(26,32))
task_codes=[ws.cell(r,4).value for r in task_rows]
for code in task_codes:
    locs=[]
    for r in range(21,39):
        for c in range(minc,maxc+1):
            if wd.cell(r,c).value == code:
                locs.append(f'{get_column_letter(c)}{r}')
    print(f'  {code!r}: {locs}')
